;----------------------------------------------------------------------
; BUCLE_PRINCIPAL: Menú -> carrera(s) -> vuelta al menú, para siempre.
;----------------------------------------------------------------------
BUCLE_PRINCIPAL:
	CALL	PREPARA_PARTIDA
	CALL	PARTIDA
	JR	BUCLE_PRINCIPAL

;----------------------------------------------------------------------
; PREPARA_PARTIDA: Menú, elección de piloto y circuito, carga de la cara 2 y datos del circuito.
;----------------------------------------------------------------------
PREPARA_PARTIDA:
	CALL	MENU
	LD	A,(CIRCUITO)
	ADD	A,A
	LD	HL,0C770h
	CALL	SUMA_A_HL
	LD	A,(HL)
	INC	HL
	LD	H,(HL)
	LD	L,A
	LD	DE,0C4B4h
	LD	BC,028Eh
	LDIR
	CALL	CARGA_CARA_2
	RET

;----------------------------------------------------------------------
; INTERCAMBIA: Intercambia BC bytes entre (IX) y (HL).
;----------------------------------------------------------------------
INTERCAMBIA:
	LD	E,(IX)
	LD	A,(HL)
	LD	(IX),A
	LD	(HL),E
	INC	IX
	INC	HL
	DEC	BC
	LD	A,B
	OR	C
	JR	nz,INTERCAMBIA
	RET

;----------------------------------------------------------------------
; TEXTO_EN: Escribe un texto: 2 bytes de posición (Spectrum) y letras; la última con
; el bit 7 puesto.
;----------------------------------------------------------------------
TEXTO_EN:
	LD	A,(HL)
	LD	(99A5h),A
	INC	HL
	LD	A,(HL)
	LD	(99A6h),A
	INC	HL
TEXTO:
	LD	A,(HL)
	AND	7Fh
	CALL	PINTA_LETRA
	BIT	7,(HL)
	INC	HL
	JR	z,TEXTO
	RET

;----------------------------------------------------------------------
; SUMA_A_HL: HL = HL + A.
;----------------------------------------------------------------------
SUMA_A_HL:
	ADD	A,L
	LD	L,A
	RET	nc
	INC	H
	RET

;----------------------------------------------------------------------
; ALEATORIO: Generador de números aleatorios (congruencial, semilla en 0893h): A = nuevo.
;----------------------------------------------------------------------
ALEATORIO:
	EXX
	LD	DE,0
	LD	H,E
	LD	L,0FDh
	LD	A,D
	OR	A
	SBC	HL,DE
	SBC	A,0
	SBC	HL,DE
	SBC	A,0
	LD	E,A
	LD	D,0
	SBC	HL,DE
	JR	nc,L08AA
	INC	HL
L08AA:
	LD	(0893h),HL
	LD	A,L
	EXX
	RET

;----------------------------------------------------------------------
; BAJA_LINEA: Siguiente línea de píxeles en una dirección de pantalla de Spectrum
; (la rutina clásica DOWN_HL).
;----------------------------------------------------------------------
BAJA_LINEA:
	INC	H
	LD	A,H
	AND	7
	RET	nz
	DEC	H
	LD	A,L
	ADD	A,20h
	LD	L,A
	ADC	A,H
	SUB	L
	AND	0F8h
	LD	H,A
	RET

;----------------------------------------------------------------------
; PINTA_MARCADOR_FIJO: Dibuja el marcador de la carrera (rótulos TIME, SCORE, LAP...).
;----------------------------------------------------------------------
PINTA_MARCADOR_FIJO:
	XOR	A
	CALL	BORRA_PANTALLA
	LD	HL,4000h
	CALL	LIMPIA_FILA
	LD	HL,4780h
	CALL	LIMPIA_FILA
	LD	HL,4680h
	CALL	LIMPIA_FILA
	LD	DE,5800h
	CALL	DIR_COLOR
	EX	DE,HL
	LD	BC,0500h
	LD	A,50h
	CALL	ATRIB_A_COLOR
	CALL	VRAM_RELLENA
	LD	DE,58A0h
	CALL	DIR_COLOR
	EX	DE,HL
	LD	A,68h
	CALL	ATRIB_A_COLOR
	LD	BC,0300h
	CALL	VRAM_RELLENA
	LD	HL,0
	LD	DE,5900h
	CALL	LB6F3
	LD	A,6Ah
	LD	(99CCh),A
	LD	HL,2407h
	CALL	TEXTO_EN
	LD	HL,5800h
	LD	DE,1Fh
	XOR	A
	LD	B,18h
L0917:
	PUSH	BC
	PUSH	HL
	EX	DE,HL
	CALL	DIR_COLOR
	EX	DE,HL
	XOR	A
	CALL	ATRIB_A_COLOR
	LD	BC,8
	CALL	VRAM_RELLENA
	POP	HL
	ADD	HL,DE
	PUSH	HL
	EX	DE,HL
	CALL	DIR_COLOR
	EX	DE,HL
	XOR	A
	CALL	ATRIB_A_COLOR
	LD	BC,8
	CALL	VRAM_RELLENA
	POP	HL
	INC	HL
	POP	BC
	DJNZ	L0917
	LD	HL,40A3h
	LD	B,5
L0944:
	LD	(99A5h),HL
	LD	A,31h
	CALL	PINTA_LETRA
	LD	A,L
	ADD	A,6
	LD	L,A
	DJNZ	L0944
	LD	HL,0E436h
	LD	DE,0E437h
	LD	BC,4
	LD	(HL),0FFh
	LDIR
	CALL	PINTA_PUNTOS
	CALL	PINTA_VUELTA
	CALL	PINTA_POSICION
	CALL	PINTA_MARCADOR
	CALL	PINTA_VELOCIDAD
	CALL	PINTA_VELOCIMETRO
	JP	L0989

;----------------------------------------------------------------------
; LIMPIA_FILA: Borra una fila de caracteres de la pantalla (dirección de Spectrum en HL).
;----------------------------------------------------------------------
LIMPIA_FILA:
	EX	DE,HL
	CALL	DIR_PATRON
	EX	DE,HL
	LD	B,20h
L097B:
	CALL	VRAM_ESCRIBE_EN
	LD	A,0FFh
	OUT	(98h),A	; VDP: datos
	LD	A,L
	ADD	A,8
	LD	L,A
	DJNZ	L097B
	RET
L0989:
	LD	BC,0500h
	LD	HL,40FAh
	LD	(99A5h),HL
L0992:
	LD	A,(ETAPA)
	CP	C
	JR	z,L09B3
	LD	A,C
	LD	HL,0E425h
	CALL	SUMA_A_HL
	LD	A,(HL)
	LD	HL,254Bh
	CALL	SUMA_A_HL
	LD	A,(HL)
	LD	(99CCh),A
	LD	A,7Fh
	CALL	PINTA_LETRA
	INC	C
	DJNZ	L0992
	RET
L09B3:
	LD	A,0F9h
L09B5:
	LD	(99CCh),A
	LD	A,C
	ADD	A,31h
	CALL	PINTA_LETRA
	INC	C
	LD	A,69h
	DJNZ	L09B5
	RET
PINTA_VELOCIMETRO:
	LD	HL,58D1h
	LD	BC,0400h
	LD	DE,69F9h
L09CD:
	LD	A,(0E6F4h)
	CP	C
	LD	A,D
	JR	nz,L09D5
	LD	A,E
L09D5:
	PUSH	HL
	PUSH	BC
	CALL	ATRIB_A_COLOR
	EX	DE,HL
	CALL	DIR_COLOR
	EX	DE,HL
	LD	BC,8
	CALL	VRAM_RELLENA
	POP	BC
	POP	HL
	INC	L
	INC	C
	DJNZ	L09CD
	RET

;----------------------------------------------------------------------
; PINTA_POSICION: Puesto en carrera (1ST, 2ND...).
;----------------------------------------------------------------------
PINTA_POSICION:
	LD	HL,40F1h
	LD	(99A5h),HL
	LD	A,69h
	LD	(99CCh),A
	LD	A,(PUESTO)
	ADD	A,A
	ADD	A,A
	ADD	A,1Bh
	LD	L,A
	ADC	A,25h
	SUB	L
	LD	H,A
	LD	A,(HL)
	CALL	PINTA_LETRA
	INC	HL
	LD	A,(HL)
	CALL	PINTA_LETRA
	INC	HL
	LD	A,6Ah
	LD	(99CCh),A
	JP	TEXTO
PINTA_VUELTA:
	LD	HL,40E6h
	LD	(99A5h),HL
	LD	A,69h
	LD	(99CCh),A
PINTA_TIEMPO_VUELTA:
	LD	HL,0E41Fh
L0A23:
	LD	B,3
L0A25:
	LD	A,(HL)
	CALL	PINTA_CIFRA
	INC	L
	LD	A,(HL)
	CALL	L0BE9
	DJNZ	L0A25
	LD	A,(HL)
	JP	PINTA_CIFRA

;----------------------------------------------------------------------
; PINTA_VELOCIDAD: Velocidad en km/h en el marcador.
;----------------------------------------------------------------------
PINTA_VELOCIDAD:
	LD	HL,40DAh
	LD	(99A5h),HL
	LD	A,69h
	LD	(99CCh),A
	LD	A,(VELOCIDAD)
	LD	L,A
	LD	H,0
	LD	E,L
	LD	D,H
	ADD	HL,HL
	ADD	HL,DE
	ADD	HL,HL
	ADD	HL,HL
	SBC	HL,DE
	LD	D,A
	LD	E,0
	EX	DE,HL
	SBC	HL,DE
	LD	A,H
	LD	C,0FFh
	LD	B,64h
L0A58:
	INC	C
	SUB	B
	JR	nc,L0A58
	ADD	A,B
	LD	B,A
	LD	A,C
	ADD	A,30h
	CALL	PINTA_LETRA
	LD	A,B
	LD	B,10
	LD	C,0FFh
L0A69:
	INC	C
	SUB	B
	JR	nc,L0A69
	ADD	A,B
	LD	B,A
	LD	A,C
	ADD	A,30h
	CALL	PINTA_LETRA
	LD	A,B
	ADD	A,30h
	CALL	PINTA_LETRA
	LD	A,(0E6F6h)
	OR	A
	LD	A,(VELOCIDAD)
	JR	z,L0A8A
	SUB	14h
	JR	nc,L0A8A
	ADD	A,14h
L0A8A:
	LD	L,A
	LD	H,0
	LD	E,L
	LD	D,H
	ADD	HL,HL
	ADD	HL,HL
	ADD	HL,DE
	LD	DE,0900h
	EX	DE,HL
	SBC	HL,DE
	XOR	A
	LD	E,L
	CALL	PSG_ESCRIBE
	INC	A
	LD	E,H
	CALL	PSG_ESCRIBE
	LD	DE,42h
	ADD	HL,DE
	LD	A,4
	LD	E,L
	CALL	PSG_ESCRIBE
	INC	A
	LD	E,H
	CALL	PSG_ESCRIBE
	CALL	EFECTOS_SONIDO
	RET
	DS 3,RELLENO
EFECTO_PEDIDO:
	DS 16,RELLENO
	DS 16,RELLENO
	DS 16,RELLENO
	DS 16,RELLENO
	DS 16,RELLENO
	DS 16,RELLENO
	DS 16,RELLENO
	DS 16,RELLENO
	DS 1,RELLENO

;----------------------------------------------------------------------
; EFECTOS_SONIDO: Reproduce el efecto de sonido en curso (canal B del PSG); se llama
; varias veces por vuelta del bucle.
;----------------------------------------------------------------------
EFECTOS_SONIDO:
	LD	A,(EFECTO_PEDIDO)
	AND	A
	CALL	nz,EMPIEZA_EFECTO
	XOR	A
	LD	(EFECTO_PEDIDO),A
	LD	A,(0AB9h)
	AND	A
	RET	z
	LD	A,(0AB5h)
	LD	HL,(0AB6h)
	ADD	A,L
	LD	L,A
	ADC	A,H
	SUB	L
	LD	H,A
	LD	A,(HL)
	AND	A
	JR	z,L0B6D
	LD	L,A
	LD	H,0
	ADD	HL,HL
	ADD	HL,HL
	LD	A,2
	LD	E,L
	CALL	PSG_ESCRIBE
	INC	A
	LD	E,H
	CALL	PSG_ESCRIBE
	LD	HL,0AB5h
	INC	(HL)
	RET
L0B6D:
	XOR	A
	LD	(0AB9h),A
	LD	(EFECTO_PEDIDO),A
	CALL	CIERRA_TONO_B
	RET
EMPIEZA_EFECTO:
	DEC	A
	ADD	A,A
	ADD	A,0BAh
	LD	L,A
	ADC	A,10
	SUB	L
	LD	H,A
	LD	A,(HL)
	INC	HL
	LD	H,(HL)
	LD	L,A
	LD	(0AB6h),HL
	LD	A,1
	LD	(0AB9h),A
	XOR	A
	LD	(0AB5h),A
	CALL	ABRE_TONO_B
	RET
ABRE_TONO_B:
	LD	A,(PSG_R7)
	AND	0FDh
	LD	(PSG_R7),A
	LD	E,A
	LD	A,7
	CALL	PSG_ESCRIBE
	RET
CIERRA_TONO_B:
	LD	A,(PSG_R7)
	OR	2
	LD	(PSG_R7),A
	LD	E,A
	LD	A,7
	CALL	PSG_ESCRIBE
	RET
PSG_R7:
	DS 1,RELLENO

;----------------------------------------------------------------------
; PSG_ESCRIBE: Registro A del PSG = E.
;----------------------------------------------------------------------
PSG_ESCRIBE:
	OUT	(0A0h),A	; PSG: registro
	EX	AF,AF'
	LD	A,E
	OUT	(0A1h),A	; PSG: escribe
	EX	AF,AF'
	RET
PINTA_PUNTOS:
	LD	HL,40C6h
	LD	(99A5h),HL
	LD	A,69h
	LD	(99CCh),A
	LD	DE,0E41Ch
L0BCA:
	LD	A,(DE)
	CALL	PINTA_CIFRA
	LD	A,27h
	CALL	PINTA_LETRA
	INC	E
	LD	A,(DE)
	CALL	PINTA_BCD
	LD	A,27h
	CALL	PINTA_LETRA
	INC	E
	LD	A,(DE)
	JP	PINTA_BCD

;----------------------------------------------------------------------
; PINTA_BCD: Escribe A como dos cifras BCD.
;----------------------------------------------------------------------
PINTA_BCD:
	PUSH	AF
	CALL	L0BE9
	POP	AF
	JR	PINTA_CIFRA
L0BE9:
	RRCA
	RRCA
	RRCA
	RRCA
PINTA_CIFRA:
	AND	15
	ADD	A,30h
	JP	PINTA_LETRA

;----------------------------------------------------------------------
; NADA: RET suelto (resto de la versión de Spectrum).
;----------------------------------------------------------------------
NADA:
	RET
	DS 16,RELLENO
	DS 2,RELLENO
L0C07:
	LD	A,(0E445h)
	INC	A
	LD	(0E445h),A
	AND	2
	RET	z
	LD	A,(ETAPA)
	CP	5
	LD	HL,24FCh
	JR	nz,L0C1E
	LD	HL,2504h
L0C1E:
	CALL	POSICION_TEXTO
	LD	A,(ETAPA)
	ADD	A,31h
	CP	36h
	JP	nz,PINTA_LETRA_GRANDE
	RET
POSICION_TEXTO:
	LD	A,(HL)
	LD	(99A5h),A
	INC	HL
	LD	A,(HL)
	LD	(99A6h),A
	INC	HL

;----------------------------------------------------------------------
; TEXTO_GRANDE: Texto con las letras grandes.
;----------------------------------------------------------------------
TEXTO_GRANDE:
	LD	A,(HL)
	AND	7Fh
	CALL	PINTA_LETRA_GRANDE
	BIT	7,(HL)
	INC	HL
	JR	z,TEXTO_GRANDE
	RET

;----------------------------------------------------------------------
; MIRA_RECORD: ¿Entra la puntuación en la tabla de récords?
;----------------------------------------------------------------------
MIRA_RECORD:
	LD	B,10
	LD	HL,257Ah
L0C47:
	PUSH	BC
	CALL	L0CAC
	JR	c,L0C56
	LD	BC,14
	ADD	HL,BC
	POP	BC
	DJNZ	L0C47
	OR	A
	RET
L0C56:
	POP	BC
	LD	A,10
	SUB	B
	LD	(0E445h),A
	DEC	B
	PUSH	HL
	JR	z,L0C73
	LD	A,B
	ADD	A,A
	LD	B,A
	ADD	A,A
	ADD	A,A
	ADD	A,A
	SUB	B
	LD	C,A
	LD	B,0
	LD	DE,2605h
	LD	HL,25F7h
	LDDR
L0C73:
	POP	DE
	LD	HL,0E41Fh
	LD	BC,4
	LDIR
	LD	A,(CIRCUITO)
	LD	(DE),A
	INC	DE
	LD	HL,0E41Ch
	LD	BC,3
	LDIR
	PUSH	DE
	LD	A,20h
	LD	(DE),A
	INC	DE
	LD	(DE),A
	INC	DE
	LD	(DE),A
	INC	DE
	LD	HL,0E42Bh
	LD	B,3
L0C97:
	LD	A,(HL)
	AND	15
	RRCA
	RRCA
	RRCA
	RRCA
	LD	C,A
	INC	HL
	LD	A,(HL)
	AND	15
	OR	C
	LD	(DE),A
	INC	HL
	INC	DE
	DJNZ	L0C97
	POP	DE
	SCF
	RET
L0CAC:
	PUSH	HL
	INC	HL
	INC	HL
	INC	HL
	LD	DE,0E422h
	LD	B,4
	OR	A
L0CB6:
	LD	A,(DE)
	SBC	A,(HL)
	DEC	DE
	DEC	HL
	DJNZ	L0CB6
	CCF
	POP	HL
	RET

;----------------------------------------------------------------------
; PIDE_INICIALES: ENTER YOUR INITIALS.
;----------------------------------------------------------------------
PIDE_INICIALES:
	PUSH	DE
	CALL	LETRAS_PEQUENAS
	LD	A,46h
	CALL	BORRA_PANTALLA
	LD	A,47h
	LD	(99CCh),A
	LD	HL,24C7h
	CALL	POSICION_TEXTO
	LD	HL,40B1h
	LD	B,20h
	LD	DE,271Bh
	LD	IX,26FCh
L0CDF:
	PUSH	BC
	LD	(99A5h),HL
	LD	A,(DE)
	CALL	PINTA_LETRA
	CALL	L0DDA
	INC	IX
