;----------------------------------------------------------------------
; CARGA_CARA_2: MULTICARGA: guarda 61E5h-7C24h (gráficos del menú) en EF00h y en la
; VRAM 0800h, lee de la cinta la cara 2 entera (6720 bytes = 12 cabezas de
; piloto de 560 bytes) sobre 61E5h, copia a 10AFh la del piloto elegido y
; vuelve a poner el menú en su sitio. El crack de disco cambia el CALL a esta
; rutina (0862h) por RET.
;----------------------------------------------------------------------
CARGA_CARA_2:
	CALL	PIDE_CARA_2
	LD	HL,61E5h
	LD	DE,MUSICA_PRESENTACION
	LD	BC,1000h
	LDIR
	LD	HL,71E5h
	LD	DE,0800h
	LD	BC,0A40h
	CALL	VRAM_COPIA
	LD	IX,61E5h
	LD	DE,1A40h
	CALL	CARGA_CINTA
	LD	A,(PILOTO)
	LD	HL,5FB5h
	LD	DE,0230h
	INC	A
	LD	B,A
L1004:
	ADD	HL,DE
	DJNZ	L1004
	LD	DE,CABEZA_PILOTO
	LD	BC,0230h
	LDIR
	LD	HL,MUSICA_PRESENTACION
	LD	DE,61E5h
	LD	BC,1000h
	LDIR
	LD	HL,71E5h
	LD	BC,0A40h
	CALL	VRAM_LEE
	CALL	PIDE_PARAR_CINTA
	RET

;----------------------------------------------------------------------
; PIDE_CARA_2: REWIND TAPE TO START OF SIDE 2.
;----------------------------------------------------------------------
PIDE_CARA_2:
	CALL	LETRAS_PEQUENAS
	LD	A,46h
	CALL	BORRA_PANTALLA
	LD	HL,1063h
	CALL	POSICION_TEXTO
	CALL	POSICION_TEXTO
	LD	HL,2800h
	LD	BC,0A40h
	XOR	A
	CALL	ATRIB_A_COLOR
	CALL	VRAM_RELLENA
	JP	LETRAS_NORMALES

;----------------------------------------------------------------------
; PIDE_PARAR_CINTA: STOP THE TAPE AND PRESS FIRE.
;----------------------------------------------------------------------
PIDE_PARAR_CINTA:
	CALL	LETRAS_PEQUENAS
	LD	A,46h
	CALL	BORRA_PANTALLA
	LD	HL,0BCA3h
	CALL	POSICION_TEXTO
	CALL	POSICION_TEXTO
L1059:
	CALL	LEE_CONTROLES
	AND	1
	JR	z,L1059
	JP	LETRAS_NORMALES
	DS 16,RELLENO
	DS 16,RELLENO
	DS 1,RELLENO
BORRA_TODO:
	LD	HL,0
	LD	BC,1800h
	XOR	A
	CALL	VRAM_RELLENA
	LD	HL,2000h
	LD	BC,1800h
	XOR	A
	CALL	ATRIB_A_COLOR
	CALL	VRAM_RELLENA
	RET
L109C:
	LD	A,46h
	LD	(99CCh),A
	LD	HL,2511h
	CALL	TEXTO_EN
	LD	A,(CREDITOS)
	ADD	A,30h
	JP	PINTA_LETRA

