	JR	nc,L6045
	ADD	HL,DE
L6045:
	ADD	HL,HL
	JR	nc,L6049
	ADD	HL,DE
L6049:
	ADD	HL,HL
	JR	nc,L604D
	ADD	HL,DE
L604D:
	ADD	HL,HL
	JR	nc,L6051
	ADD	HL,DE
L6051:
	LD	A,(5ADBh)
	OR	A
	RET	p
	LD	A,L
	CPL
	LD	L,A
	LD	A,H
	CPL
	LD	H,A
	INC	HL
	RET
PREPARA_CARAS:
	LD	B,11h
	LD	HL,0EA00h
	XOR	A
L6064:
	CALL	L6074
	LD	DE,6
	ADD	HL,DE
	INC	A
	CP	12
	JR	nz,L6071
	XOR	A
L6071:
	DJNZ	L6064
	RET
L6074:
	PUSH	AF
	PUSH	BC
	PUSH	HL
	EX	DE,HL
	ADD	A,A
	ADD	A,0D6h
	LD	L,A
	ADC	A,34h
	SUB	L
	LD	H,A
	LD	A,(HL)
	INC	HL
	LD	H,(HL)
	LD	L,A
	LD	B,34h
L6086:
	PUSH	BC
	CALL	LBD1A
	LD	A,60h
	ADD	A,E
	LD	E,A
	ADC	A,D
	SUB	E
	LD	D,A
	POP	BC
	DJNZ	L6086
	POP	HL
	POP	BC
	POP	AF
	RET
VRAM_DESTINO:
	DS 2,RELLENO
VUELCA_LOGO:
	LD	B,8
	LD	HL,0200h
	LD	(VRAM_DESTINO),HL
	LD	HL,MUSICA_PRESENTACION
	CALL	L60A9
	RET
L60A9:
	PUSH	BC
	PUSH	HL
	EX	DE,HL
	LD	HL,(VRAM_DESTINO)
	CALL	VRAM_ESCRIBE_EN
	LD	A,20h
L60B4:
	EX	AF,AF'
	LD	H,D
	LD	L,E
	LD	A,(HL)
	INC	H
	OR	(HL)
	OUT	(98h),A	; VDP: datos
	INC	H
	LD	A,(HL)
	INC	H
	OR	(HL)
	OUT	(98h),A	; VDP: datos
	INC	H
	LD	A,(HL)
	INC	H
	OR	(HL)
	OUT	(98h),A	; VDP: datos
	INC	H
	LD	A,(HL)
	INC	H
	OR	(HL)
	OUT	(98h),A	; VDP: datos
	INC	H
	LD	A,(HL)
	INC	H
	OR	(HL)
	OUT	(98h),A	; VDP: datos
	INC	H
	LD	A,(HL)
	INC	H
	OR	(HL)
	OUT	(98h),A	; VDP: datos
	INC	H
	LD	A,(HL)
	INC	H
	OR	(HL)
	OUT	(98h),A	; VDP: datos
	INC	H
	LD	A,(HL)
	INC	H
	OR	(HL)
	OUT	(98h),A	; VDP: datos
	INC	H
	INC	DE
	EX	AF,AF'
	DEC	A
	JP	nz,L60B4
	LD	HL,(VRAM_DESTINO)
	INC	H
	LD	(VRAM_DESTINO),HL
	POP	HL
	LD	BC,20h
	ADD	HL,BC
	POP	BC
	DEC	B
	JP	nz,L60A9
	RET

;----------------------------------------------------------------------
; ARRANQUE: Pila en 6182h, tabla de colores Spectrum->MSX en 0400h, música de
; presentación y bucle principal.
;----------------------------------------------------------------------
ARRANQUE:
	DI
	LD	SP,INT_VACIA
	CALL	HAZ_TABLA_ATRIB
	CALL	MUSICA_PRESENTACION
	JP	BUCLE_PRINCIPAL

;----------------------------------------------------------------------
; HAZ_TABLA_ATRIB: Rellena 0400h-04FFh: para cada atributo de Spectrum (tinta, papel, brillo)
; el byte de color del VDP equivalente (llama a ATRIB_A_COLOR 256 veces).
;----------------------------------------------------------------------
HAZ_TABLA_ATRIB:
	LD	HL,0400h
	XOR	A
	LD	B,A
L6111:
	PUSH	AF
	PUSH	BC
	CALL	ATRIB_A_COLOR
	LD	(HL),A
	INC	HL
	POP	BC
	POP	AF
	INC	A
	DJNZ	L6111
	RET
	DS 16,RELLENO
	DS 16,RELLENO
	DS 16,RELLENO
	DS 16,RELLENO
	DS 16,RELLENO
	DS 16,RELLENO
	DS 4,RELLENO

;----------------------------------------------------------------------
; INT_VACIA: Rutina de interrupción durante el juego: solo lee el estado del VDP (99h)
; para bajar la petición y vuelve. No hay música durante la carrera.
;----------------------------------------------------------------------
INT_VACIA:
	PUSH	AF
	IN	A,(99h)	; VDP: control
	POP	AF
	EI
	RETI

;----------------------------------------------------------------------
; VRAM_RELLENA: Rellena BC bytes de VRAM desde HL con el valor A.
;----------------------------------------------------------------------
VRAM_RELLENA:
	PUSH	AF
	CALL	VRAM_ESCRIBE_EN
	POP	AF
VRAM_RELLENA_SIGUE:
	OUT	(98h),A	; VDP: datos
	EX	AF,AF'
	DEC	BC
	LD	A,B
	OR	C
	RET	z
	EX	AF,AF'
	JP	VRAM_RELLENA_SIGUE

;----------------------------------------------------------------------
; VRAM_COPIA: Copia BC bytes de RAM (HL) a VRAM (DE).
;----------------------------------------------------------------------
VRAM_COPIA:
	DI
	EX	DE,HL
	CALL	VRAM_ESCRIBE_EN
	EX	DE,HL
L619F:
	LD	A,(HL)
	OUT	(98h),A	; VDP: datos
	INC	HL
	DEC	BC
	LD	A,B
	OR	C
	JP	nz,L619F
	RET

;----------------------------------------------------------------------
; VRAM_LEE: Lee BC bytes de VRAM 0800h a RAM (DE).
;----------------------------------------------------------------------
VRAM_LEE:
	DI
	EX	DE,HL
	LD	HL,0800h
	CALL	VRAM_LEE_EN
	EX	DE,HL
L61B3:
	IN	A,(98h)	; VDP: datos
	LD	(HL),A
	INC	HL
	DEC	BC
	LD	A,B
	OR	C
	JP	nz,L61B3
	RET

;----------------------------------------------------------------------
; VRAM_ESCRIBE_EN: Prepara el VDP para escribir en la dirección HL. Los dos EX (SP),HL son
; solo una espera (38 ciclos) para el TMS9918.
;----------------------------------------------------------------------
VRAM_ESCRIBE_EN:
	DI
	LD	A,L
	OUT	(99h),A	; VDP: control
	LD	A,H
	AND	3Fh
	OR	40h
	OUT	(99h),A	; VDP: control
	EX	(SP),HL
	EX	(SP),HL
	RET

;----------------------------------------------------------------------
; VRAM_LEE_EN: Prepara el VDP para leer en la dirección HL (con la misma espera).
;----------------------------------------------------------------------
VRAM_LEE_EN:
	DI
	LD	A,L
	OUT	(99h),A	; VDP: control
	LD	A,H
	AND	3Fh
	OUT	(99h),A	; VDP: control
	EX	(SP),HL
	EX	(SP),HL
	RET

;----------------------------------------------------------------------
; PON_BORDE: Color del borde (registro 7 del VDP) = A.
;----------------------------------------------------------------------
PON_BORDE:
	OUT	(99h),A	; VDP: control
	LD	A,87h
	OUT	(99h),A	; VDP: control
	RET

;----------------------------------------------------------------------
