;----------------------------------------------------------------------
; LEE_JOYSTICK: Joystick del puerto A por el PSG (registro 14). OJO: pone a 1 los bits 6
; y 7 del registro 7, es decir, el puerto A como SALIDA, contra la norma MSX.
;----------------------------------------------------------------------
LEE_JOYSTICK:
	LD	A,7
	OUT	(0A0h),A	; PSG: registro
	IN	A,(0A2h)	; PSG: lee
	OR	0C0h
	PUSH	AF
	LD	A,7
	OUT	(0A0h),A	; PSG: registro
	POP	AF
	OUT	(0A1h),A	; PSG: escribe
	LD	A,14
	OUT	(0A0h),A	; PSG: registro
	IN	A,(0A2h)	; PSG: lee
	LD	E,1
	RRA
	JR	c,L9881
	SET	1,E
L9881:
	RRA
	JR	c,L9886
	SET	2,E
L9886:
	RRA
	JR	c,L988B
	SET	4,E
L988B:
	RRA
	JR	c,L9890
	SET	3,E
L9890:
	RRA
	RET	nc
	RES	0,E
	RET

;----------------------------------------------------------------------
; ATRIB_A_COLOR: Traduce un atributo de Spectrum (FBPPPIII) al byte de color del VDP
; (tinta en el nibble alto, papel en el bajo). Tablas en 98C4h (normal) y
; 98CCh (brillo).
;----------------------------------------------------------------------
ATRIB_A_COLOR:
	PUSH	HL
	PUSH	DE
	PUSH	BC
	PUSH	AF
	LD	HL,98C4h
	BIT	6,A
	JR	z,L98A3
	LD	HL,98CCh
L98A3:
	PUSH	HL
	AND	7
	LD	E,A
	LD	D,0
	ADD	HL,DE
	LD	A,(HL)
	RRCA
	RRCA
	RRCA
	RRCA
	LD	C,A
	POP	HL
	POP	AF
	AND	38h
	SRA	A
	SRA	A
	SRA	A
	LD	E,A
	LD	D,0
	ADD	HL,DE
	LD	A,(HL)
	OR	C
	POP	BC
	POP	DE
	POP	HL
	RET
	DS 16,RELLENO

;----------------------------------------------------------------------
; DIR_PATRON: Dirección de pantalla de Spectrum (DE) -> dirección de patrones del VDP.
;----------------------------------------------------------------------
DIR_PATRON:
	PUSH	AF
	LD	A,D
	AND	7
	LD	(98EEh),A
	LD	A,D
	AND	18h
	LD	D,A
	LD	A,E
	RLCA
	RLCA
	RLCA
	AND	7
	OR	D
	LD	D,A
	LD	A,E
	AND	1Fh
	ADD	A,A
	ADD	A,A
	ADD	A,A
	ADD	A,0
	LD	E,A
	POP	AF
	RET

;----------------------------------------------------------------------
; DIR_COLOR: Dirección de atributos de Spectrum (DE) -> dirección de colores del VDP.
;----------------------------------------------------------------------
DIR_COLOR:
	PUSH	AF
	PUSH	HL
	EX	DE,HL
	LD	DE,0A800h
	ADD	HL,DE
	PUSH	HL
	SRL	H
	RR	L
	SRL	H
	RR	L
	SRL	H
	RR	L
	SRL	H
	RR	L
	SRL	H
	RR	L
	LD	H,L
	LD	L,0
	EX	DE,HL
	POP	HL
	LD	H,0
	LD	A,L
	AND	1Fh
	LD	L,A
	ADD	HL,HL
	ADD	HL,HL
	ADD	HL,HL
	ADD	HL,DE
	LD	DE,2000h
	ADD	HL,DE
	EX	DE,HL
	POP	HL
	POP	AF
	RET

;----------------------------------------------------------------------
; LEE_TECLA: Barre las filas 0-8 del teclado y devuelve en A el código ASCII de la
; primera tecla pulsada (tabla en 9951h), o 0.
;----------------------------------------------------------------------
LEE_TECLA:
	PUSH	HL
	PUSH	BC
	LD	DE,0F000h
L992A:
	LD	A,D
	OUT	(0AAh),A	; PPI: fila de teclado / motor cinta
	IN	A,(0A9h)	; PPI: teclado (columnas)
	LD	B,8
L9931:
	RRCA
	JR	nc,L9941
	INC	E
	DJNZ	L9931
	INC	D
	LD	A,0F9h
	CP	D
	JR	nz,L992A
	XOR	A
	POP	BC
	POP	HL
	RET
L9941:
	LD	A,1
L9943:
	RRCA
	DJNZ	L9943
	LD	C,E
	LD	E,A
	LD	HL,9951h
	ADD	HL,BC
	LD	A,(HL)
	OR	A
	POP	BC
	POP	HL
	RET
	DS 16,RELLENO
	DS 16,RELLENO
	DS 16,RELLENO
	DS 16,RELLENO
	DS 8,RELLENO

;----------------------------------------------------------------------
; PINTA_LETRA: Escribe la letra A en la posición de 99A5h (patrones y color 99CCh).
;----------------------------------------------------------------------
PINTA_LETRA:
	EXX
	LD	L,A
	LD	H,0
	ADD	HL,HL
	ADD	HL,HL
	ADD	HL,HL
	LD	A,H
	ADD	A,4
	LD	H,A
	LD	DE,0
	LD	A,E
	INC	A
	LD	(99A5h),A
	PUSH	HL
	LD	HL,8000h
	AND	A
	SBC	HL,DE
	POP	HL
	JR	c,L99D8
	CALL	DIR_PATRON
	PUSH	DE
	LD	BC,8
	CALL	VRAM_COPIA
	POP	HL
	LD	A,(99E2h)
	AND	A
	JR	z,L99D6
	LD	BC,2000h
	ADD	HL,BC
	LD	A,0
	CALL	ATRIB_A_COLOR
	LD	BC,8
	CALL	VRAM_RELLENA
L99D6:
	EXX
	RET
L99D8:
	LD	B,8
L99DA:
	LD	A,(HL)
	LD	(DE),A
	INC	D
	INC	HL
	DJNZ	L99DA
	EXX
	RET
	DS 1,RELLENO
ESPEJO_COCHE:
	LD	A,(0E432h)
	DEC	A
	LD	HL,0D84Ch
	LD	BC,0AD8h
	JR	z,L99F5
	LD	HL,0D256h
	LD	BC,05F6h
L99F5:
	LD	IX,88D8h
	CALL	INTERCAMBIA
	RET
MOTOR_ENCENDIDO:
	LD	A,(PSG_R7)
	AND	0FAh
	LD	(PSG_R7),A
	LD	E,A
	LD	A,7
	CALL	PSG_ESCRIBE
	LD	A,8
	LD	E,13
	CALL	PSG_ESCRIBE
	INC	A
	LD	E,15
	CALL	PSG_ESCRIBE
	INC	A
	LD	E,13
	CALL	PSG_ESCRIBE
	RET
SILENCIO:
	LD	A,(PSG_R7)
	OR	7
	LD	(PSG_R7),A
	LD	E,A
	LD	A,7
	CALL	PSG_ESCRIBE
	INC	A
	LD	E,0
	CALL	PSG_ESCRIBE
	INC	A
	CALL	PSG_ESCRIBE
	INC	A
	CALL	PSG_ESCRIBE
	RET
SILENCIO_TODO:
	LD	A,0BFh
	LD	(PSG_R7),A
	LD	E,A
	LD	A,7
	CALL	PSG_ESCRIBE
	RET

;----------------------------------------------------------------------
; PARTIDA: Las 5 etapas de un circuito (y la etapa extra).
;----------------------------------------------------------------------
PARTIDA:
	CALL	PUNTOS_A_CERO
L9A4B:
	LD	HL,CREDITOS
	DEC	(HL)
L9A4F:
	CALL	SILENCIO
	CALL	CARRERA
	CALL	SILENCIO
	CALL	SILENCIO_TODO
	LD	A,(ETAPA)
	ADD	A,25h
	LD	H,0E4h
	LD	L,A
	LD	A,(PUESTO)
	LD	(HL),A
	CP	3
	JR	nc,L9A8B
	LD	A,(ETAPA)
	INC	A
	LD	(ETAPA),A
	CP	5
	JR	c,L9A4F
	JR	z,L9A7D
	CALL	ESPEJO_COCHE
	JR	L9A95
L9A7D:
	LD	HL,0E424h
	LD	B,6
	XOR	A
L9A83:
	OR	(HL)
	JR	nz,L9A95
	INC	L
	DJNZ	L9A83
	JR	L9A4F
L9A8B:
	CALL	SUMA_PUNTOS_ETAPA
	CALL	CONTINUAR
	JR	c,L9A4B
	JR	L9A9B
L9A95:
	CALL	PODIO
	CALL	SUMA_PUNTOS_ETAPA
L9A9B:
	CALL	RECORDS
	CALL	nc,GAME_OVER
	RET

;----------------------------------------------------------------------
; CARRERA: Una carrera: prepara y entra en el bucle de imágenes.
;----------------------------------------------------------------------
CARRERA:
	CALL	PANTALLA_ETAPA
	LD	A,(ETAPA)
	CP	5
	JR	c,L9AB8
	LD	A,(CIRCUITO)
	AND	1
	INC	A
	LD	(0E432h),A
	CALL	ESPEJO_COCHE
L9AB8:
	XOR	A
	LD	(0E44Ah),A
	LD	(0E44Bh),A
	LD	(0E44Ch),A
	LD	(0E521h),A
	LD	(0E523h),A
	LD	A,2
	LD	(0E522h),A
	CALL	PREPARA_CARRERA
	CALL	MOTOR_ENCENDIDO

;----------------------------------------------------------------------
; BUCLE_CARRERA: Bucle de una imagen: espera a la interrupción (HALT) y hace todo.
; En un HB-20P da ~6,6 imágenes por segundo.
;----------------------------------------------------------------------
BUCLE_CARRERA:
	EI
	HALT
	DI
	CALL	AVANZA_PISTA
	CALL	CALCULA_BORDES
	CALL	VUELCA_BUFER
	CALL	DESPLAZA_HORIZONTE
	CALL	EFECTOS_SONIDO
	CALL	NADA
	CALL	CUENTA_TIEMPO
	CALL	MUEVE_RIVALES
	CALL	PINTA_SUELO
	CALL	PINTA_PISTA
	CALL	EFECTOS_SONIDO
	CALL	PINTA_RIVALES
	CALL	EFECTOS_SONIDO
	CALL	PINTA_JUGADOR
	CALL	MUEVE_DECORADO
	LD	A,(0E433h)
	OR	A
	CALL	CHOQUE
	LD	A,(0E44Ah)
	CP	3
	CALL	nz,SEMAFORO
	LD	A,(0E6E3h)
	OR	A
	CALL	z,ORDENA_CARRERA
	CALL	PINTA_MARCADOR
	CALL	MIRA_CHOQUES
	CALL	PINTA_VUELTA
	CALL	PINTA_VELOCIDAD
	LD	A,(0E44Ch)
	OR	A
	CALL	nz,CARTELES
	LD	HL,0E6B8h
	LD	A,(HL)
	OR	A
	CALL	nz,MENSAJES_CARRERA
	CALL	CUENTA_FIN
	CALL	SALTO
	LD	A,(0E6E3h)
	OR	A
	JR	z,L9B53
	LD	A,(VELOCIDAD)
	LD	HL,0E6E4h
	SUB	(HL)
	LD	(VELOCIDAD),A
	JR	nc,L9B5A
	XOR	A
	LD	(VELOCIDAD),A
	JP	L9B5A
L9B53:
	LD	A,(0E6CAh)
	CP	7
	JR	c,L9B61
L9B5A:
	LD	A,(0E6E3h)
	OR	A
	CALL	z,CONTROL_JUGADOR
L9B61:
	LD	A,(0E6E5h)
	OR	A
	JP	z,BUCLE_CARRERA
	CALL	SILENCIO
	CALL	SILENCIO_TODO
	RET

;----------------------------------------------------------------------
; AVANZA_PISTA: Avanza por el circuito según la velocidad y calcula la curva.
;----------------------------------------------------------------------
AVANZA_PISTA:
	CALL	PROYECTA_TRAMOS
	LD	HL,(0E6F2h)
	LD	DE,(0E466h)
	OR	A
	SBC	HL,DE
	LD	A,L
	ADD	A,80h
	LD	(0E46Fh),A
	LD	(9BF1h),A
	LD	DE,3Ch
	ADD	HL,DE
	LD	(9BB9h),HL
	EXX
	LD	HL,0E470h
	EXX
	LD	A,(0E6F0h)
	ADD	A,20h
	DS 2,RELLENO	; LD	IYL,A
	DS 3,RELLENO	; LD	IYH,0EAh
	LD	A,(0E6EFh)
	AND	0E0h
	LD	C,A
	DS 2,RELLENO	; LD	IXL,A
	DS 3,RELLENO	; LD	IXH,0E8h
	LD	B,15h
L9BA8:
	LD	E,(IY)
	LD	HL,(9BB9h)
	DS 2,RELLENO	; INC	IYL
	LD	A,E
	RLA
	SBC	A,A
	LD	D,A
	ADD	HL,DE
	LD	(9BB9h),HL
	LD	DE,3Ch
	LD	A,(IX)
	LD	HL,0
	ADD	A,A
	JR	nc,L9BC7
	LD	L,E
	LD	H,D
	ADD	HL,HL
L9BC7:
	ADD	A,A
	JR	nc,L9BCB
	ADD	HL,DE
L9BCB:
	ADD	HL,HL
	ADD	A,A
	JR	nc,L9BD0
	ADD	HL,DE
L9BD0:
	ADD	HL,HL
	ADD	A,A
	JR	nc,L9BD5
	ADD	HL,DE
L9BD5:
	ADD	HL,HL
	ADD	A,A
	JR	nc,L9BDA
	ADD	HL,DE
L9BDA:
	ADD	HL,HL
	ADD	A,A
	JR	nc,L9BDF
	ADD	HL,DE
L9BDF:
	ADD	HL,HL
	ADD	A,A
	JR	nc,L9BE4
	ADD	HL,DE
L9BE4:
	ADD	HL,HL
	ADD	A,A
	JR	nc,L9BE9
	ADD	HL,DE
L9BE9:
	RL	L
	LD	A,H
	ADC	A,0
	NEG
	ADD	A,80h
	EXX
	LD	(HL),A
	INC	L
	EXX
	DS 2,RELLENO	; INC	IXL
	DJNZ	L9BA8
	EXX
	LD	(HL),0A0h
	EXX
	RET

;----------------------------------------------------------------------
; PROYECTA_TRAMOS: Proyección en perspectiva de los tramos de la pista que se ven.
;----------------------------------------------------------------------
PROYECTA_TRAMOS:
	LD	A,(0E6EFh)
	AND	0E0h
	DS 2,RELLENO	; LD	IXL,A
	DS 3,RELLENO	; LD	IXH,0E8h
	EXX
	LD	HL,0E681h
	EXX
	LD	B,15h
	LD	HL,(0E6F2h)
	LD	DE,4Ch
	OR	A
	SBC	HL,DE
	JP	nc,L9C84
	ADD	HL,DE
	LD	A,L
	CPL
	LD	L,A
	LD	A,H
	CPL
	LD	H,A
	INC	HL
	LD	DE,3Ch
	ADD	HL,DE
	LD	(9C2Ch),HL
L9C2B:
	LD	DE,3Ch
	LD	A,(IX)
	LD	HL,0
	ADD	A,A
	JR	nc,L9C3A
	LD	L,E
	LD	H,D
	ADD	HL,HL
L9C3A:
	ADD	A,A
	JR	nc,L9C3E
	ADD	HL,DE
L9C3E:
	ADD	HL,HL
	ADD	A,A
	JR	nc,L9C43
	ADD	HL,DE
L9C43:
	ADD	HL,HL
	ADD	A,A
	JR	nc,L9C48
	ADD	HL,DE
L9C48:
	ADD	HL,HL
	ADD	A,A
	JR	nc,L9C4D
	ADD	HL,DE
L9C4D:
	ADD	HL,HL
	ADD	A,A
	JR	nc,L9C52
	ADD	HL,DE
L9C52:
	ADD	HL,HL
	ADD	A,A
	JR	nc,L9C57
	ADD	HL,DE
L9C57:
	ADD	HL,HL
	ADD	A,A
	JR	nc,L9C5C
	ADD	HL,DE
L9C5C:
	RL	L
	LD	A,H
	ADC	A,0
	NEG
	ADD	A,80h
	EXX
	LD	(HL),A
	INC	L
	EXX
	DS 2,RELLENO	; INC	IXL
	DJNZ	L9C2B
	EXX
	LD	(HL),0A0h
	DEC	L
	LD	A,(HL)
	ADD	A,3
	AND	0F8h
	LD	C,A
	CP	81h
	JR	nc,L9C82
	LD	HL,0E43Eh
	SUB	(HL)
	LD	(HL),C
	INC	L
	LD	(HL),A
L9C82:
	EXX
	RET
L9C84:
	LD	HL,0E681h
	LD	DE,0E682h
	LD	BC,14h
	LD	(HL),90h
	LDIR
