;----------------------------------------------------------------------
; VUELCA_BUFER: Manda a la VRAM (0800h) los 4096 bytes de patrones de las 16 filas de
; caracteres de la zona de juego, desde el búfer EF00h-FEFFh. ~28 % del tiempo.
